  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Guest account this session belongs to. {@link
  /// multi_user_todo_app_guests.id}
  multi_user_todo_app_guest_id String @db.Uuid

  /// Device identifier for guest session continuity across requests.
  device_id String

  /// Device fingerprint hash for session security and fraud detection.
  fingerprint String

  /// Client IP address for session tracking and security auditing.
  ip String

  /// Last known page URL for session context.
  href String

  /// Referrer URL from the request for session source tracking.
  referrer String

  /// Session creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Session expiration timestamp for security cleanup.
