  /// invalidated.
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  member multi_user_todo_app_members @relation(fields: [member_id], references: [id], onDelete: Cascade)

  //----
  // INDEXES
  //----
  @@unique([member_id])
